import { ref } from 'vue'

export type Theme = 'light' | 'dark'

const STORAGE_KEY = 'agent-hub.theme'
const theme = ref<Theme>('light')

function readInitial(): Theme {
  try {
    const stored = window.localStorage.getItem(STORAGE_KEY)
    if (stored === 'light' || stored === 'dark') return stored
  } catch {
    // localStorage 不可用时退回系统偏好。
  }
  return window.matchMedia?.('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'
}

export function applyTheme(next: Theme): void {
  theme.value = next
  document.documentElement.dataset.theme = next
  document.documentElement.classList.toggle('dark', next === 'dark')
  try {
    window.localStorage.setItem(STORAGE_KEY, next)
  } catch {
    // 忽略隐私模式写入失败。
  }
}

export function useTheme() {
  function toggle(): void {
    applyTheme(theme.value === 'dark' ? 'light' : 'dark')
  }

  return { theme, toggle, setTheme: applyTheme }
}

if (typeof document !== 'undefined') {
  applyTheme(readInitial())
}
=== AccountMenu ===
<script setup lang="ts">
import { onMounted, onUnmounted, ref } from 'vue'

import type { Theme } from '@/composables/useTheme'
import type { User } from '@/types'

const props = defineProps<{
  user: User | null
  theme: Theme
}>()

const emit = defineEmits<{
  settings: []
  diagnostics: []
  theme: []
  logout: []
}>()

const open = ref(false)
const root = ref<HTMLElement | null>(null)

function toggle(): void {
  open.value = !open.value
}

function close(): void {
  open.value = false
}

function initials(): string {
  const name = props.user?.display_name?.trim() || props.user?.email || 'AH'
  return name.slice(0, 2).toUpperCase()
}

function onDocumentClick(event: MouseEvent): void {
  if (!open.value) return
  const target = event.target as Node | null
  if (root.value && target && !root.value.contains(target)) close()
}

function onEscape(event: KeyboardEvent): void {
  if (event.key === 'Escape') close()
}

function openSettings(): void {
  emit('settings')
  close()
}

function openDiagnostics(): void {
  emit('diagnostics')
  close()
}

function toggleTheme(): void {
  emit('theme')
  close()
}

function logout(): void {
  emit('logout')
  close()
}

onMounted(() => {
  document.addEventListener('click', onDocumentClick)
  document.addEventListener('keydown', onEscape)
})

onUnmounted(() => {
  document.removeEventListener('click', onDocumentClick)
  document.removeEventListener('keydown', onEscape)
})
</script>

<template>
  <div ref="root" class="account-wrap">
    <button
      class="account"
      type="button"
      aria-label="账号菜单"
      aria-haspopup="menu"
      :aria-expanded="open"
      @click="toggle"
    >
      <span class="avatar">{{ initials() }}</span>
      <span class="account-text">
        <span class="account-name">{{ user?.display_name || '未登录' }}</span>
        <span class="account-sub">{{ user?.email || '' }}</span>
      </span>

