然后写 CommandPalette.vue。这个组件比较大，需要仔细写。

组件设计：

```vue
<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRouter } from 'vue-router'

import EmptyState from '@/components/common/EmptyState.vue'
import ErrorState from '@/components/common/ErrorState.vue'
import LoadingSkeleton from '@/components/common/LoadingSkeleton.vue'
import { conversationsApi } from '@/api/conversations'
import { useChatStore } from '@/stores/chat'
import { filterPalettePages, matchMessages, type PalettePage } from '@/utils/commandPalette'
import type { Conversation, SystemCapabilities } from '@/types'

const props = defineProps<{
  open: boolean
  capabilities?: SystemCapabilities | null
}>()

const emit = defineEmits<{ close: [] }>()

const router = useRouter()
const chat = useChatStore()

const inputRef = ref<HTMLInputElement | null>(null)
const query = ref('')
const activeIndex = ref(0)

const conversations = ref<Conversation[]>([])
const conversationLoading = ref(false)
const conversationError = ref<string | null>(null)
let debounceTimer: ReturnType<typeof setTimeout> | null = null
let abortController: AbortController | null = null

interface PaletteItem {
  id: string
  group: 'page' | 'conversation' | 'message'
  label: string
  hint?: string
  run: () => void
}

const pages = computed(() => filterPalettePages(query.value, props.capabilities))
const messages = computed(() => (chat.state.conversationId ? matchMessages(chat.messages, query.value) : []))
const items = computed<PaletteItem[]>(() => {
  const list: PaletteItem[] = pages.value.map((page) => ({
    id: `page-${page.id}`,
    group: 'page',
    label: page.label,
    hint: page.description,
    run: () => goPage(page),
  }))
  for (const conversation of conversations.value) {
    list.push({
      id: `conversation-${conversation.id}`,
      group: 'conversation',
      label: conversation.title,
      hint: `${conversation.message_count} 条消息`,
      run: () => goConversation(conversation.id),
    })
  }
  for (const message of messages.value) {
    list.push({
      id: `message-${message.id}`,
      group: 'message',
      label: message.content.slice(0, 60),
      hint: message.role === 'user' ? '我' : '助手',
      run: () => goMessage(message.id),
    })
  }
  return list
})
```

键盘导航：activeIndex 在 items 范围内移动（分组连续列表，展示时分组渲染但索引全局）。

展示：按组渲染，但 activeIndex 全局。用 computed 分组并计算每项 index：

```ts
const groupedItems = computed(() => {
  const groups: Array<{ key: string; label: string; items: Array<{ item: PaletteItem; index: number }> }> = []
  let cursor = 0
  for (const [key, label] of [['page','页面'],['conversation','会话'],['message','当前会话消息']]) {
    const list = items.value.filter(i => i.group === key).map(item => ({ item, index: cursor++ }))
    if (list.length) groups.push({ key, label, items: list })
  }
  return groups
})
```

但 conversation 组在无查询时为空（只有输入 ≥1 才搜索）。messages 同理。

监听 open：打开时清空 query、重置 activeIndex、focus input；关闭时恢复触发元素焦点（memo lastFocused）。

防抖搜索：

```ts
watch(query, (value) => {
  activeIndex.value = 0
  if (debounceTimer) clearTimeout(debounceTimer)
  abortController?.abort()
  conversationError.value = null
  const keyword = value.trim()
  if (!keyword) {
    conversations.value = []
    conversationLoading.value = false
    return
  }
  conversationLoading.value = true
  debounceTimer = setTimeout(() => { void searchConversations(keyword) }, 250)
})

async function searchConversations(keyword: string) {
  abortController = new AbortController()
  try {
    const page = await conversationsApi.list({ q: keyword, status: 'active', limit: 8 })
    if (abortController.signal.aborted) return
    conversations.value = page.items
  } catch (error) {
    if (!abortController.signal.aborted) conversationError.value = ...
  } finally {
    if (!abortController.signal.aborted) conversationLoading.value = false
  }
}
```

但 conversationsApi.list 不支持 signal 参数。AbortController 只能防止结果写回（检查 signal.aborted）。请求本身不会取消。可接受（mock 即时；真实请求 250ms 防抖后发出）。类型上 abortController 只用于标记。

键盘处理：

```ts
function onKeydown(event: KeyboardEvent) {
  if (event.key === 'Escape') { event.preventDefault(); close(); return }
  if (event.key === 'ArrowDown') { event.preventDefault(); move(1) }
  if (event.key === 'ArrowUp') { event.preventDefault(); move(-1) }
  if (event.key === 'Enter') { event.preventDefault(); execute() }
}
```

挂在面板容器或 input 上。用 input 的 @keydown 即可（焦点在 input）。

执行：
```ts
function execute() {
  const item = items.value[activeIndex.value]
  if (!item) return
  item.run()
}

function close() {
  emit('close')
  // 恢复焦点在 AppLayout 处理？组件内记录 lastFocused
}

function goPage(page: PalettePage) {
  close()
  void router.push({ name: page.route })
}

function goConversation(id: string) {
  close()
  if (chat.state.streaming) chat.stop()
  void router.push({ name: 'chat', query: { c: id } })
}

function goMessage(id: string) {
  close()
  chat.requestScrollToMessage(id)
  void router.push({ name: 'chat', query: { c: chat.state.conversationId ?? undefined } })
}
```

注意 goMessage：当前会话 id 存在（因为消息组只在有会话时出现）。query c 设置为当前会话 id。如果已经在 chat，router.push 同路径同 query 不会触发导航，但 ChatView 的 watch pendingScrollMessageId 会触发。

消息组是否只在当前路由为 chat 时显示？设计要求「仅在当前路由为 chat 且 chat.state.conversationId 存在时出现」。CommandPalette 挂 AppLayout，可以用 useRoute 判断。

```ts
const route = useRoute()
const messages = computed(() =>
  route.name === 'chat' && chat.state.conversationId
    ? matchMessages(chat.messages, query.value)
    : [],
)
```

