}''')

s=s.replace('''.skill-main {
  flex: 1;
  min-width: 0;
}''','''.skill-open {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
  text-align: left;
}''')

s=s.replace('''.skill-desc {
  margin-top: 4px;''','''.skill-desc {
  display: block;
  margin-top: 4px;''')

open(p,'w',encoding='utf8').write(s)
print('patched')
